import React, { createContext, useState, useContext } from 'react';

const AuthContext = createContext();

export const useAuth = () => useContext(AuthContext);

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [flowData, setFlowData] = useState({
    email: '',
    password: '',
    sessionId: null,
    currentStep: 'login',
    methods: [],
    phoneNumber: null
  });

  const login = async (params) => {
    // params may be { email, password } or { provider, token }
    setLoading(true);
    setError(null);
    try {
      const response = await fetch('/api/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(params)
      });
      const data = await response.json();
      if (data.success) {
        setFlowData(prev => ({
          ...prev,
          ...params,
          sessionId: data.sessionId,
          currentStep: data.nextStep || '2fa'
        }));
        if (data.nextStep === 'complete') {
          setUser({ email: params.email || data.user?.email });
        }
        return { success: true, nextStep: data.nextStep };
      } else {
        setError(data.message || 'Login failed');
        return { success: false, error: data.message };
      }
    } catch (err) {
      setError(err.message);
      return { success: false, error: err.message };
    } finally {
      setLoading(false);
    }
  };

  const submitOTP = async (code) => {
    setLoading(true);
    try {
      const response = await fetch('/api/verify-otp', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          sessionId: flowData.sessionId, 
          code 
        })
      });

      const data = await response.json();

      if (data.success) {
        setUser({ email: flowData.email });
        setFlowData(prev => ({ ...prev, currentStep: 'complete' }));
      }

      return data;
    } catch (err) {
      setError(err.message);
      return { success: false };
    } finally {
      setLoading(false);
    }
  };

  const logout = () => {
    setUser(null);
    setFlowData({
      email: '',
      password: '',
      sessionId: null,
      currentStep: 'login',
      methods: [],
      phoneNumber: null
    });
  };

  const value = {
    user,
    loading,
    error,
    flowData,
    login,
    submitOTP,
    logout
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};
